import React, { useState, useEffect } from "react";
import axios from "axios";

const Products = () => {
  const [products, setProducts] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [file, setFile] = useState(null); // Image file state
  const [selectedProduct, setSelectedProduct] = useState(null);
const [showViewModal, setShowViewModal] = useState(false);

const modalOverlayStyle = {
  position: "fixed",
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  backgroundColor: "rgba(0,0,0,0.6)",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  zIndex: 1000,
};

const modalContentStyle = {
  backgroundColor: "#fff",
  padding: "20px",
  borderRadius: "10px",
  maxWidth: "400px",
  width: "90%",
  boxShadow: "0 5px 15px rgba(0,0,0,0.3)",
  textAlign: "center",
};




  const [formData, setFormData] = useState({
    name: "",
    category: "",
    price: "",
    brand: "",
  });

  //  Fetch products from backend
  useEffect(() => {
    const fetchProducts = async () => {
      try {
        const res = await axios.get("http://localhost:5000/api/users/allproducts");
        setProducts(res.data);
      } catch (err) {
        console.error("Error fetching products:", err);
      }
    };
    fetchProducts();
  }, []);

  // Handle text input changes
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  // Handle image input
  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  //  Add product to backend
  const handleAddProduct = async (e) => {
    e.preventDefault();

    const formDataToSend = new FormData();
    formDataToSend.append("name", formData.name);
    formDataToSend.append("category", formData.category);
    formDataToSend.append("price", formData.price);
    formDataToSend.append("brand", formData.brand);
    formDataToSend.append("image", file); //  actual image file

    try {
      const res = await axios.post("http://localhost:5000/api/users/addproduct", formDataToSend, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });

      setProducts([res.data, ...products]); // Add new product to UI
      setFormData({ name: "", category: "", price: "", brand: "" });
      setFile(null);
      setShowForm(false);
    } catch (err) {
      console.error(" Failed to add product:", err);
      alert(err.response?.data?.message || "Error adding product");
    }
  };
const handleDelete = async (id) => {
  if (!window.confirm("Are you sure you want to delete this product?")) return;

  try {
    await axios.delete(`http://localhost:5000/api/users/product/${id}`);
    setProducts(products.filter((p) => p._id !== id));
  } catch (err) {
    console.error(" Failed to delete:", err);
    alert("Failed to delete product");
  }
};


  const DropdownWithRadios = ({ title, options, selected, setSelected, icon }) => {
    const [isOpen, setIsOpen] = useState(false);
    const toggleDropdown = () => setIsOpen(!isOpen);

    return (
      <div>
  <div className="dropdown-container" style={{ position: "relative", display: "inline-block", zIndex:"100" }}>

       <button
        onClick={toggleDropdown}
        className="btn"
        style={{
          backgroundColor: 'white',
          border: '2px solid #e9ecef',
          borderRadius: '12px',
          padding: '12px 20px',
          fontSize: '14px',
          fontWeight: 600,
          minWidth: '130px',
          height: '45px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '8px',
          cursor: 'pointer',
          transition: 'all 0.3s ease',
          boxShadow: '0 2px 8px rgba(0, 0, 0, 0.05)',
          outline: 'none',
        }}
        onMouseEnter={(e) => {
          e.target.style.borderColor = '#007bff';
          e.target.style.boxShadow = '0 0 0 3px rgba(0, 123, 255, 0.1)';
        }}
        onMouseLeave={(e) => {
          e.target.style.borderColor = '#e9ecef';
          e.target.style.boxShadow = '0 2px 8px rgba(0, 0, 0, 0.05)';
        }}
      >
        {title}
        {icon ? <span style={{ fontSize: '16px' }}>{icon}</span> : <span style={{ fontSize: '10px' }}>▼</span>}
      </button>
        {isOpen && (
             <div
  style={{
    position: "absolute",
    top: "100%",
    left: 0,
    backgroundColor: "#fff",
    zIndex: 9999,
    borderRadius: "12px",
    maxHeight: "250px",
    overflowY: "auto",
    padding: "15px",
    width: "220px",
    border: "2px solid #e9ecef",
    boxShadow: "0 8px 25px rgba(0, 0, 0, 0.15)",
    marginTop: "8px",
    backdropFilter: "blur(10px)",
  }}
>




            {title === "Category" && (
              <ol style={{ margin: 0, paddingLeft: 0, listStyle: "none" }}>
                {/* Add/remove category options here */}
                <li><label style={{ display: "flex", alignItems: "center", padding: "8px 12px", cursor: "pointer", borderRadius: "8px", transition: "background-color 0.2s ease", marginBottom: "4px" }} onMouseEnter={(e) => e.target.style.backgroundColor = "#f8f9fa"} onMouseLeave={(e) => e.target.style.backgroundColor = "transparent"}><input type="radio" name="category" value="electronics" onChange={(e) => setSelected(e.target.value)} style={{ marginRight: "10px", accentColor: "#007bff" }} /> Electronics</label></li>
                <li><label style={{ display: "flex", alignItems: "center", padding: "8px 12px", cursor: "pointer", borderRadius: "8px", transition: "background-color 0.2s ease", marginBottom: "4px" }} onMouseEnter={(e) => e.target.style.backgroundColor = "#f8f9fa"} onMouseLeave={(e) => e.target.style.backgroundColor = "transparent"}><input type="radio" name="category" value="clothing" onChange={(e) => setSelected(e.target.value)} style={{ marginRight: "10px", accentColor: "#007bff" }} /> Clothing</label></li>
                <li><label style={{ display: "flex", alignItems: "center", padding: "8px 12px", cursor: "pointer", borderRadius: "8px", transition: "background-color 0.2s ease", marginBottom: "4px" }} onMouseEnter={(e) => e.target.style.backgroundColor = "#f8f9fa"} onMouseLeave={(e) => e.target.style.backgroundColor = "transparent"}><input type="radio" name="category" value="books" onChange={(e) => setSelected(e.target.value)} style={{ marginRight: "10px", accentColor: "#007bff" }} /> Books</label></li>
                <li><label style={{ display: "flex", alignItems: "center", padding: "8px 12px", cursor: "pointer", borderRadius: "8px", transition: "background-color 0.2s ease", marginBottom: "4px" }} onMouseEnter={(e) => e.target.style.backgroundColor = "#f8f9fa"} onMouseLeave={(e) => e.target.style.backgroundColor = "transparent"}><input type="radio" name="category" value="sports" onChange={(e) => setSelected(e.target.value)} style={{ marginRight: "10px", accentColor: "#007bff" }} /> Sports</label></li>
                <li><label style={{ display: "flex", alignItems: "center", padding: "8px 12px", cursor: "pointer", borderRadius: "8px", transition: "background-color 0.2s ease", marginBottom: "4px" }} onMouseEnter={(e) => e.target.style.backgroundColor = "#f8f9fa"} onMouseLeave={(e) => e.target.style.backgroundColor = "transparent"}><input type="radio" name="category" value="home" onChange={(e) => setSelected(e.target.value)} style={{ marginRight: "10px", accentColor: "#007bff" }} /> Home & Garden</label></li>
              </ol>
            )}


            {title === "Brand" && (
              <ol style={{ margin: 0, paddingLeft: 20 }}>
                {/* Add/remove brand options here */}
                <li><label style={{ display: "block", padding: "5px 0", cursor: "pointer" }}><input type="radio" name="brand" value="apple" onChange={(e) => setSelected(e.target.value)} /> Apple</label></li>
                <li><label style={{ display: "block", padding: "5px 0", cursor: "pointer" }}><input type="radio" name="brand" value="samsung" onChange={(e) => setSelected(e.target.value)} /> Samsung</label></li>
                <li><label style={{ display: "block", padding: "5px 0", cursor: "pointer" }}><input type="radio" name="brand" value="nike" onChange={(e) => setSelected(e.target.value)} /> Nike</label></li>
                <li><label style={{ display: "block", padding: "5px 0", cursor: "pointer" }}><input type="radio" name="brand" value="adidas" onChange={(e) => setSelected(e.target.value)} /> Adidas</label></li>
                <li><label style={{ display: "block", padding: "5px 0", cursor: "pointer" }}><input type="radio" name="brand" value="sony" onChange={(e) => setSelected(e.target.value)} /> Sony</label></li>
              </ol>
            )}


            {title === "Price" && (
              <ol style={{ margin: 0, paddingLeft: 20 }}>
                {/* Add/remove price options here */}
                <li><label style={{ display: "block", padding: "5px 0", cursor: "pointer" }}><input type="radio" name="price" value="0-100" onChange={(e) => setSelected(e.target.value)} /> $0 - $100</label></li>
                <li><label style={{ display: "block", padding: "5px 0", cursor: "pointer" }}><input type="radio" name="price" value="100-500" onChange={(e) => setSelected(e.target.value)} /> $100 - $500</label></li>
                <li><label style={{ display: "block", padding: "5px 0", cursor: "pointer" }}><input type="radio" name="price" value="500-1000" onChange={(e) => setSelected(e.target.value)} /> $500 - $1000</label></li>
                <li><label style={{ display: "block", padding: "5px 0", cursor: "pointer" }}><input type="radio" name="price" value="1000+" onChange={(e) => setSelected(e.target.value)} /> $1000+</label></li>
              </ol>
            )}
          </div>
        )}
      </div>
      </div>
    );
  };

  // Add state for filter selections
  const [categoryFilter, setCategoryFilter] = useState("");
  const [brandFilter, setBrandFilter] = useState("");
  const [priceFilter, setPriceFilter] = useState("");

  return (
    <div style={{ backgroundColor: "white" }}>
      <h1 style={{ textAlign: "center", marginTop: "0px" , marginBottom:'0px'}}>PRODUCTS</h1>
      <div className="filterbar" style={{ 
        display: "flex", 
        justifyContent: "center", 
        alignItems: "center", 
        gap: "15px", 
        margin: "30px auto",
        padding: "25px 30px",
        backgroundColor: "#f8f9fa",
        borderRadius: "15px",
        boxShadow: "0 4px 20px rgba(0, 0, 0, 0.08)",
        border: "1px solid #e9ecef",
        maxWidth: "1200px",
        flexWrap: "wrap",
        position: "relative",
        backdropFilter: "blur(10px)",
      }}>
        <DropdownWithRadios 
          title="Category" 
          options={[]} 
          selected={categoryFilter} 
          setSelected={setCategoryFilter}
          icon="▼"
        />
        <DropdownWithRadios 
          title="Brand" 
          options={[]} 
          selected={brandFilter} 
          setSelected={setBrandFilter}
          icon="▼"
        />
        <DropdownWithRadios 
          title="Price" 
          options={[]} 
          selected={priceFilter} 
          setSelected={setPriceFilter}
          icon="▼"
        />
        <input 
          className="search" 
          type="text" 
          placeholder="Search products..." 
          style={{ 
            backgroundColor: 'white',
            borderRadius: '12px',
            padding: '12px 20px',
            width: '400px',
            height: '45px',
            border: '2px solid #e9ecef',
            fontSize: '14px',
            outline: 'none',
            transition: 'all 0.3s ease',
            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.05)',
          }}
          onFocus={(e) => {
            e.target.style.borderColor = '#007bff';
            e.target.style.boxShadow = '0 0 0 3px rgba(0, 123, 255, 0.1)';
          }}
          onBlur={(e) => {
            e.target.style.borderColor = '#e9ecef';
            e.target.style.boxShadow = '0 2px 8px rgba(0, 0, 0, 0.05)';
          }}
        />

        <button style={{
          backgroundColor: '#6c757d',
          color: 'white',           
          border: 'none',           
          borderRadius: '12px',              
          padding: '12px 24px',                
          fontSize: '14px',                   
          fontWeight: 600,                 
          minWidth: '130px',            
          height: '45px',                  
          display: 'flex',
          alignItems: 'center',              
          justifyContent: 'center',
          gap: '8px',
          cursor: 'pointer',
          transition: 'all 0.3s ease',
          boxShadow: '0 2px 8px rgba(0, 0, 0, 0.1)',
        }}
        onMouseEnter={(e) => {
          e.target.style.backgroundColor = '#5a6268';
          e.target.style.transform = 'translateY(-2px)';
          e.target.style.boxShadow = '0 4px 12px rgba(0, 0, 0, 0.15)';
        }}
        onMouseLeave={(e) => {
          e.target.style.backgroundColor = '#6c757d';
          e.target.style.transform = 'translateY(0)';
          e.target.style.boxShadow = '0 2px 8px rgba(0, 0, 0, 0.1)';
        }}
        >Reset Filter</button>

{/* Add Product Button */}

        <button style={{
          backgroundColor: '#28a745',
          color: 'white',           
          border: 'none',           
          borderRadius: '12px',              
          padding: '12px 24px',                
          fontSize: '14px',                   
          fontWeight: 600,                 
          minWidth: '130px',            
          height: '45px',                  
          display: 'flex',
          alignItems: 'center',              
          justifyContent: 'center',
          gap: '8px',
          cursor: 'pointer',
          transition: 'all 0.3s ease',
          boxShadow: '0 2px 8px rgba(40, 167, 69, 0.2)',
        }} 
        onClick={() => setShowForm(true)}
        onMouseEnter={(e) => {
          e.target.style.backgroundColor = '#218838';
          e.target.style.transform = 'translateY(-2px)';
          e.target.style.boxShadow = '0 4px 12px rgba(40, 167, 69, 0.3)';
        }}
        onMouseLeave={(e) => {
          e.target.style.backgroundColor = '#28a745';
          e.target.style.transform = 'translateY(0)';
          e.target.style.boxShadow = '0 2px 8px rgba(40, 167, 69, 0.2)';
        }}
        >
          <span style={{ fontSize: '16px', marginRight: '4px' }}>+</span>
          Add Product
        </button>

      </div>



      {/*  Modal Form */}
      {showForm && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h2>Add New Product</h2>
            <form onSubmit={handleAddProduct} encType="multipart/form-data">
              <input
                type="text"
                name="name"
                placeholder="Name"
                value={formData.name}
                onChange={handleChange}
                required
              />
              <input
                type="text"
                name="category"
                placeholder="Category"
                value={formData.category}
                onChange={handleChange}
                required
              />
              <input
                type="number"
                name="price"
                placeholder="Price"
                value={formData.price}
                onChange={handleChange}
                required
              />
              <input
                type="text"
                name="brand"
                placeholder="Brand"
                value={formData.brand}
                onChange={handleChange}
                required
              />
              <input
                type="file"
                name="image"
                accept="image/*"
                onChange={handleFileChange}
                required
              />
              <div className="form-buttons">
                <button type="submit" className="square-btn view">
                  Submit
                </button>
                <button
                  type="button"
                  className="square-btn delete"
                  onClick={() => setShowForm(false)}
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/*  Product Cards Grid */}
      <div className="product-grid">
        {products.map((product, index) => (
          <div key={index} className="square-card">
            <img
              src={`http://localhost:5000/uploads/${product.image}`}
              alt={product.name}
              className="square-img"
            />
            <div className="square-info">
              <h4>{product.name}</h4>
              <p className="product-meta">{product.category}</p>
              <p className="product-meta">₹{product.price}</p>
              <p className="product-meta">{product.brand}</p>
            </div>
            <div className="button-row">
              <button className="square-btn delete" onClick={() => handleDelete(product._id)}>
  Delete
</button>

              <button
  className="square-btn view"
  onClick={() => {
    setSelectedProduct(product);
    setShowViewModal(true);
  }}
>
  View
</button>

            </div>
            {showViewModal && selectedProduct && (
  <div className="modal-overlay" style={modalOverlayStyle}>
    <div className="modal-content" style={modalContentStyle}>
      <h2>Product Details</h2>
      <img
        src={`http://localhost:5000/uploads/${selectedProduct.image}`}
        alt={selectedProduct.name}
        style={{ width: "100%", maxHeight: "250px", objectFit: "cover", borderRadius: "10px" }}
      />
      <p><strong>Name:</strong> {selectedProduct.name}</p>
      <p><strong>Category:</strong> {selectedProduct.category}</p>
      <p><strong>Price:</strong> ₹{selectedProduct.price}</p>
      <p><strong>Brand:</strong> {selectedProduct.brand}</p>

      <button
        className="square-btn delete"
        onClick={() => setShowViewModal(false)}
      >
        Close
      </button>
    </div>
  </div>
)}

          </div>
        ))}
      </div>
    </div>
  );
};


export default Products;
